  'ofp.stamp': '09 — Plans & pricing',
  'ofp.title': 'One subscription,<br><em class="accent">four</em> lengths.',
  'ofp.lede': 'The month to try, the quarter to settle in, the half year and the year to pay less each month. Same profile, same features: only the length changes.',
