  'ofp.tableSub': 'The price paid, the month it stands for, and the saving it carries.',
  'ofp.tableCol': 'Plan',
  'ofp.faqTitle': 'Pricing questions',
  'ofp.faqSub': 'Short answers to the questions that come up most often.',
  'ofp.ctaTitle': 'Unsure about the length?',
  'ofp.ctaText': 'Tell us your trade and the pace of your requests: we answer with the length that fits, without a sales pitch.',
  'ofp.ctaBtn': 'Open an account',
  'ofp.ctaAlt': 'See B2B requests',
