  'ofp.r6a': 'Email support',
  'ofp.r6b': 'Named contact, 48 h reply',
  'ofp.r6c': 'Named contact, quarterly review',
  'ofp.q1': 'What does the subscription cost?',
  'ofp.a1': 'The month is 1 500 DZD, the quarter 4 050, the half year 7 650 and the year 14 400. Discounts are 10%, 15% and 20% by length. Each country reads these amounts in its own currency.',
  'ofp.q2': 'How is the subscription paid?',
  'ofp.a2': 'In one payment, for the length chosen, in the currency of the country read on the page. No commission is taken on the quote requests you receive.',
  'ofp.q3': 'Can I change the length, or stop?',
  'ofp.a3': 'Yes, any time from your account: the new length applies at once, at no cost. The profile does not disappear, it simply returns to its own pace.',
  'ofp.q4': 'Does the price change by country?',
  'ofp.a4': 'The reference price is written in dinars. Each country reads it in its own money, rounded to its step, and some markets pay a share adjusted to their purchasing power. The exact amount is confirmed at payment.',
  'ofp.q5': 'Are the quarter or the half year cheaper?',
  'ofp.a5': 'The quarter gets a 10% discount, the half year 15%, and the year 20%. The longer the commitment, the lower the monthly price.',
  'ofp.q6': 'What happens at the end of the length?',
  'ofp.a6': 'The subscription stops on the agreed date, with no surprise renewal: a reminder is sent before the end, and you choose whether to extend.',

