/**
 * Les trois langues de CE fichier, prises à part des dix-neuf autres.
 *
 * Le dictionnaire fusionné ci-dessus ne dit pas d'où vient une clé : le
 * contrôle de parité de la console a besoin de comparer chaque fichier à
 * lui-même, et celui-ci est le plus gros de tous. On l'expose donc tel quel,
 * sans rien changer à ce que lit le site.
 */
export const baseDict: Record<Lang, Dict> = { fr, ar, en };